#include "complex_numbers.h"

#include <cmath>

namespace complex_numbers {

ComplexNumber::ComplexNumber(double real_part, double imaginary_part)
    : real_part_(real_part), imaginary_part_(imaginary_part) {}

double ComplexNumber::real() const {
    return real_part_;
}

double ComplexNumber::imag() const {
    return imaginary_part_;
}

ComplexNumber ComplexNumber::conjugate() const {
    return ComplexNumber(real_part_, -imaginary_part_);
}

double ComplexNumber::abs() const {
    return std::hypot(real_part_, imaginary_part_);
}

ComplexNumber ComplexNumber::operator+(const ComplexNumber& other) const {
    return ComplexNumber(real_part_ + other.real_part_,
                         imaginary_part_ + other.imaginary_part_);
}

ComplexNumber ComplexNumber::operator-(const ComplexNumber& other) const {
    return ComplexNumber(real_part_ - other.real_part_,
                         imaginary_part_ - other.imaginary_part_);
}

ComplexNumber ComplexNumber::operator*(const ComplexNumber& other) const {
    return ComplexNumber(
        real_part_ * other.real_part_ - imaginary_part_ * other.imaginary_part_,
        imaginary_part_ * other.real_part_ + real_part_ * other.imaginary_part_);
}

ComplexNumber ComplexNumber::operator/(const ComplexNumber& other) const {
    const double denominator = other.real_part_ * other.real_part_ +
                               other.imaginary_part_ * other.imaginary_part_;

    return ComplexNumber(
        (real_part_ * other.real_part_ +
         imaginary_part_ * other.imaginary_part_) /
            denominator,
        (imaginary_part_ * other.real_part_ -
         real_part_ * other.imaginary_part_) /
            denominator);
}

ComplexNumber& ComplexNumber::operator+=(const ComplexNumber& other) {
    real_part_ += other.real_part_;
    imaginary_part_ += other.imaginary_part_;
    return *this;
}

ComplexNumber& ComplexNumber::operator-=(const ComplexNumber& other) {
    real_part_ -= other.real_part_;
    imaginary_part_ -= other.imaginary_part_;
    return *this;
}

ComplexNumber& ComplexNumber::operator*=(const ComplexNumber& other) {
    *this = *this * other;
    return *this;
}

ComplexNumber& ComplexNumber::operator/=(const ComplexNumber& other) {
    *this = *this / other;
    return *this;
}

ComplexNumber ComplexNumber::exp() const {
    const double magnitude = std::exp(real_part_);
    return ComplexNumber(magnitude * std::cos(imaginary_part_),
                         magnitude * std::sin(imaginary_part_));
}

ComplexNumber operator+(double value, const ComplexNumber& number) {
    return ComplexNumber(value, 0.0) + number;
}

ComplexNumber operator-(double value, const ComplexNumber& number) {
    return ComplexNumber(value, 0.0) - number;
}

ComplexNumber operator*(double value, const ComplexNumber& number) {
    return ComplexNumber(value, 0.0) * number;
}

ComplexNumber operator/(double value, const ComplexNumber& number) {
    return ComplexNumber(value, 0.0) / number;
}

bool operator==(const ComplexNumber& lhs, const ComplexNumber& rhs) {
    return lhs.real() == rhs.real() && lhs.imag() == rhs.imag();
}

bool operator!=(const ComplexNumber& lhs, const ComplexNumber& rhs) {
    return !(lhs == rhs);
}

ComplexNumber exp(const ComplexNumber& number) {
    return number.exp();
}

}  // namespace complex_numbers
